import { useState, type FormEvent, type ReactNode } from 'react';
import { useLocation, Link } from 'wouter';
import { useQueryClient } from '@tanstack/react-query';
import { ArrowDownRight, ArrowUpRight, Banknote, Bell, Check, ChevronDown, CircleAlert, ClipboardList, FileDown, Loader2, MoreHorizontal, PackageOpen, Plus, RefreshCw, Search, Settings2, ShieldCheck, SlidersHorizontal, TrendingUp, Wheat, X } from 'lucide-react';
import {
  getGetFarmerQueryKey, getGetMillingTransactionQueryKey, getGetReportsSummaryQueryKey,
  getGetDashboardSummaryQueryKey, getListFarmersQueryKey, getListInventoryQueryKey,
  getListMillingTransactionsQueryKey, getListNotificationsQueryKey, getListPaymentsQueryKey,
  useCreateFarmer, useCreateInventoryItem, useCreateMillingTransaction, useCreatePayment, useDeleteFarmer,
  useDemoLogin, useGetCurrentUser, useGetDashboardActivity, useGetDashboardSummary, useGetFarmer,
  useGetMillingTransaction, useGetReportsSummary, useHealthCheck, useListFarmers, useListInventory,
  useListMillingTransactions, useListNotifications, useListPayments, useUpdateFarmer, useUpdateInventoryItem,
  useUpdateMillingTransaction,
  type MillingTransaction, type Role,
} from '@workspace/api-client-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { AppShell, Initials } from '@/components/shell';

const peso = (value = 0) => `₱${value.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const date = (value?: string) => value ? new Date(value).toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }) : '—';
const titleCase = (value = '') => value.toLowerCase().replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());

function LoadingState({ label = 'Loading records' }: { label?: string }) {
  return <div className="space-y-3" data-testid="state-loading">{[1, 2, 3].map((item) => <div key={item} className="h-14 animate-pulse rounded-xl bg-muted/60" />)}<div className="flex items-center gap-2 pt-2 font-mono-app text-[10px] uppercase tracking-[.18em] text-muted-foreground"><Loader2 size={13} className="animate-spin" />{label}</div></div>;
}
function ErrorState({ message = 'The records could not be loaded.', retry }: { message?: string; retry?: () => void }) {
  return <div className="flex min-h-40 flex-col items-center justify-center rounded-2xl border border-dashed border-[hsl(var(--chart-4)/.45)] bg-[hsl(var(--chart-4)/.05)] p-6 text-center" data-testid="state-error"><CircleAlert className="mb-3 text-[hsl(var(--chart-4))]" size={23} /><p className="text-sm font-bold">{message}</p><p className="mt-1 text-xs text-muted-foreground">Check the mill connection, then try again.</p>{retry && <Button onClick={retry} variant="outline" size="sm" className="mt-4" data-testid="button-retry"><RefreshCw size={14} /> Retry</Button>}</div>;
}
function EmptyState({ label, action, onAction }: { label: string; action?: string; onAction?: () => void }) {
  return <div className="flex min-h-48 flex-col items-center justify-center rounded-2xl border border-dashed border-border bg-card/50 p-8 text-center" data-testid="state-empty"><span className="mb-3 grid h-11 w-11 place-items-center rounded-2xl bg-secondary text-primary"><PackageOpen size={20} /></span><p className="text-sm font-bold">{label}</p><p className="mt-1 max-w-xs text-xs text-muted-foreground">There is nothing here yet. New records will appear as the desk receives them.</p>{action && onAction && <Button size="sm" className="mt-4" onClick={onAction} data-testid="button-empty-action"><Plus size={14} /> {action}</Button>}</div>;
}
function StatusPill({ value, tone }: { value: string; tone?: 'green' | 'gold' | 'red' | 'blue' }) {
  const color = tone ?? (value.includes('LOW') || value.includes('PENDING') ? 'gold' : value.includes('OUT') || value.includes('CANCEL') ? 'red' : value.includes('COMPLETED') || value.includes('HEALTHY') ? 'green' : 'blue');
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 font-mono-app text-[9px] font-medium uppercase tracking-[.1em] ${color === 'green' ? 'bg-[hsl(var(--chart-1)/.12)] text-[hsl(var(--chart-1))]' : color === 'gold' ? 'bg-[hsl(var(--accent)/.2)] text-[hsl(var(--primary))]' : color === 'red' ? 'bg-[hsl(var(--chart-4)/.12)] text-[hsl(var(--chart-4))]' : 'bg-[hsl(var(--chart-5)/.12)] text-[hsl(var(--chart-5))]'}`} data-testid={`status-${value.toLowerCase()}`}>{titleCase(value)}</span>;
}
function PageIntro({ eyebrow, title, description, action, onAction }: { eyebrow: string; title: string; description: string; action?: string; onAction?: () => void }) {
  return <div className="mb-7 flex flex-col justify-between gap-5 md:flex-row md:items-end page-enter"><div><div className="mb-2 flex items-center gap-2 font-mono-app text-[10px] uppercase tracking-[.2em] text-muted-foreground"><span className="h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent))]" />{eyebrow}</div><h2 className="font-display text-4xl leading-none tracking-[-.04em] text-primary md:text-[46px]">{title}</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p></div>{action && onAction && <Button onClick={onAction} className="self-start md:self-end" data-testid="button-page-action"><Plus size={16} />{action}</Button>}</div>;
}
function StatCard({ label, value, meta, icon: Icon, accent = 'primary', delay = '' }: { label: string; value: string; meta: string; icon: typeof Wheat; accent?: string; delay?: string }) {
  return <div className={`page-enter ${delay} group rounded-2xl border border-border/80 bg-card p-5 shadow-[0_10px_28px_hsl(var(--primary)/.035)] transition-transform hover:-translate-y-1`} data-testid={`card-stat-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="mb-7 flex items-start justify-between"><span className="font-mono-app text-[10px] uppercase tracking-[.16em] text-muted-foreground">{label}</span><span className={`grid h-9 w-9 place-items-center rounded-xl ${accent === 'gold' ? 'bg-accent/30 text-primary' : accent === 'red' ? 'bg-[hsl(var(--chart-4)/.12)] text-[hsl(var(--chart-4))]' : 'bg-primary/10 text-primary'}`}><Icon size={17} /></span></div><div className="text-3xl font-extrabold tracking-[-.05em] text-primary">{value}</div><div className="mt-2 flex items-center gap-1 text-xs text-muted-foreground">{meta.startsWith('+') ? <ArrowUpRight size={13} className="text-[hsl(var(--chart-1))]" /> : null}{meta}</div></div>;
}
function Toolbar({ search, setSearch, placeholder = 'Search records' }: { search: string; setSearch: (value: string) => void; placeholder?: string }) {
  return <div className="flex flex-col gap-3 sm:flex-row sm:items-center"><div className="relative min-w-0 flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={16} /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={placeholder} className="h-11 border-border bg-background pl-10" data-testid="input-search" /></div><Button variant="outline" className="h-11" data-testid="button-filters"><SlidersHorizontal size={15} /> Filters <ChevronDown size={14} /></Button></div>;
}
function TableFrame({ children }: { children: ReactNode }) {
  return <div className="overflow-hidden rounded-2xl border border-border bg-card shadow-[0_10px_28px_hsl(var(--primary)/.035)]"><div className="overflow-x-auto">{children}</div></div>;
}
function TableEmpty({ colSpan = 5 }: { colSpan?: number }) {
  return <tbody><tr><td colSpan={colSpan}><EmptyState label="No records match this view" /></td></tr></tbody>;
}

export function LoginPage() {
  const [, setLocation] = useLocation();
  const [selected, setSelected] = useState<Role>('ADMIN');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('demo1234');
  const health = useHealthCheck({ query: { retry: false } });
  const login = useDemoLogin();
  const roles: { role: Role; label: string; description: string; route: string }[] = [
    { role: 'ADMIN', label: 'Admin', description: 'Full operations console', route: '/dashboard' },
    { role: 'STAFF', label: 'Staff', description: 'Daily mill desk', route: '/dashboard' },
    { role: 'FARMER', label: 'Farmer', description: 'Private crop & payment view', route: '/my-dashboard' },
    { role: 'CUSTOMER', label: 'Customer', description: 'Private transaction view', route: '/my-dashboard' },
  ];
  const submit = (event: React.FormEvent) => { event.preventDefault(); const chosen = roles.find((role) => role.role === selected)!; const address = email || `${selected.toLowerCase()}@camarin.local`; login.mutate({ data: { email: address, password } }, { onSuccess: (user) => setLocation(user.role === 'FARMER' || user.role === 'CUSTOMER' ? '/my-dashboard' : '/dashboard'), onError: () => { localStorage.setItem('camarin-demo-role', selected); setLocation(chosen.route); } }); };
  return <div className="grain flex min-h-[100dvh] bg-[hsl(var(--background))]"><div className="hidden w-[43%] flex-col justify-between bg-primary p-10 text-primary-foreground lg:flex"><div><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-[15px] bg-accent text-accent-foreground"><Wheat size={22} /></span><div><div className="font-extrabold tracking-[-.04em]">Camarin</div><div className="font-mono-app text-[9px] uppercase tracking-[.2em] text-primary-foreground/55">Rice mill operations</div></div></div><div className="mt-28 max-w-md"><div className="font-mono-app text-[10px] uppercase tracking-[.24em] text-accent">Sitio Camarin · Dimataling</div><h1 className="mt-5 font-display text-7xl leading-[.89] tracking-[-.06em]">From palay<br /><em className="text-accent">to plenty.</em></h1><p className="mt-7 max-w-sm text-sm leading-7 text-primary-foreground/65">A clear, shared desk for receiving harvests, guiding every batch through the mill, and keeping every farmer account in view.</p></div></div><div className="flex items-center gap-2 font-mono-app text-[10px] uppercase tracking-[.16em] text-primary-foreground/50"><span className={`h-2 w-2 rounded-full ${health.isError ? 'bg-[hsl(var(--chart-4))]' : 'bg-[hsl(var(--accent))]'}`} />{health.isError ? 'Mill service offline' : 'Mill service connected'}</div></div><div className="flex flex-1 items-center justify-center p-6 sm:p-10"><div className="w-full max-w-[480px] page-enter"><div className="mb-10 lg:hidden"><span className="font-display text-3xl font-semibold text-primary">Camarin.</span><span className="ml-2 font-mono-app text-[9px] uppercase tracking-[.2em] text-muted-foreground">Rice mill</span></div><div className="mb-8"><div className="mb-3 font-mono-app text-[10px] uppercase tracking-[.2em] text-muted-foreground">Demo access</div><h2 className="font-display text-4xl tracking-[-.04em] text-primary">Good morning, operator.</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">Choose a view to step inside the Camarin workspace.</p></div><div className="mb-7 grid grid-cols-2 gap-2 sm:grid-cols-4">{roles.map((item) => <button key={item.role} onClick={() => setSelected(item.role)} className={`rounded-xl border p-3 text-left transition-all ${selected === item.role ? 'border-primary bg-primary text-primary-foreground shadow-lg' : 'border-border bg-card hover:border-primary/30'}`} data-testid={`button-role-${item.role.toLowerCase()}`}><div className={`mb-3 grid h-7 w-7 place-items-center rounded-lg ${selected === item.role ? 'bg-accent text-accent-foreground' : 'bg-secondary text-primary'}`}><ShieldCheck size={14} /></div><div className="text-xs font-extrabold">{item.label}</div><div className={`mt-1 text-[10px] leading-4 ${selected === item.role ? 'text-primary-foreground/60' : 'text-muted-foreground'}`}>{item.description}</div></button>)}</div><form onSubmit={submit} className="space-y-4"><label className="block"><span className="mb-2 block text-xs font-bold">Email address <span className="font-normal text-muted-foreground">(optional for demo)</span></span><Input value={email} onChange={(event) => setEmail(event.target.value)} placeholder={`${selected.toLowerCase()}@camarin.local`} className="h-12 bg-card" data-testid="input-email" /></label><label className="block"><span className="mb-2 block text-xs font-bold">Password</span><Input type="password" value={password} onChange={(event) => setPassword(event.target.value)} className="h-12 bg-card" data-testid="input-password" /></label><Button type="submit" disabled={login.isPending} className="h-12 w-full text-sm" data-testid="button-sign-in">{login.isPending ? <Loader2 className="animate-spin" size={17} /> : <ArrowUpRight size={17} />} Enter {selected.toLowerCase()} view</Button></form><p className="mt-6 text-center font-mono-app text-[9px] uppercase tracking-[.16em] text-muted-foreground">Demo environment · Dimataling, Zamboanga del Sur</p></div></div></div>;
}

export function DashboardPage({ portal = false }: { portal?: boolean }) {
  const summary = useGetDashboardSummary({ period: 'month' }, { query: { retry: false } });
  const activity = useGetDashboardActivity({ query: { retry: false } });
  const current = useGetCurrentUser({ query: { retry: false } });
  const [period, setPeriod] = useState<'today' | 'week' | 'month' | 'year'>('month');
  const dynamicSummary = useGetDashboardSummary({ period }, { query: { retry: false, queryKey: getGetDashboardSummaryQueryKey({ period }) } });
  const data = dynamicSummary.data ?? summary.data;
  const kpis = data?.kpis ?? {};
  const activities = activity.data ?? [];
  const isPortal = portal;
  return <AppShell portal={isPortal}><PageIntro eyebrow={isPortal ? 'Personal account' : 'Today at the mill'} title={isPortal ? 'Your harvest, in view.' : 'Keep the floor moving.'} description={isPortal ? 'A private ledger of your milling activity, balances, and receipts at Sitio Camarin.' : `Good day${current.data?.name ? `, ${current.data.name.split(' ')[0]}` : ''}. Here is the shape of the operation for this period.`} action={!isPortal ? 'Receive palay' : undefined} onAction={!isPortal ? () => window.dispatchEvent(new Event('open-receive')) : undefined} /><div className="mb-5 flex justify-end"><div className="flex rounded-xl border border-border bg-card p-1">{(['today', 'week', 'month', 'year'] as const).map((item) => <button key={item} onClick={() => setPeriod(item)} className={`rounded-lg px-3 py-2 font-mono-app text-[10px] uppercase tracking-wider transition ${period === item ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-primary'}`} data-testid={`button-period-${item}`}>{item}</button>)}</div></div>{summary.isLoading || dynamicSummary.isLoading ? <LoadingState label="Reading the mill ledger" /> : summary.isError && !data ? <ErrorState retry={() => summary.refetch()} /> : <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[['Received this month', `${(kpis.receivedVolume ?? kpis.millingVolume ?? 0).toLocaleString()} kg`, '+8.4% vs last month', Wheat, 'gold'], ['In milling', `${kpis.inMilling ?? kpis.activeTransactions ?? 0}`, 'batches on the floor', ClipboardList, 'primary'], ['Outstanding', peso(kpis.outstanding ?? kpis.outstandingBalance ?? 0), 'across active accounts', Banknote, 'red'], ['Net revenue', peso(kpis.revenue ?? kpis.netRevenue ?? 0), '+12.1% vs last month', TrendingUp, 'primary']].map(([label, value, meta, icon, accent], index) => <StatCard key={String(label)} label={String(label)} value={String(value)} meta={String(meta)} icon={icon as typeof Wheat} accent={String(accent)} delay={`stagger-${index + 1}`} />)}</div><div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><section className="rounded-2xl border border-border bg-card p-5 md:p-6"><div className="mb-7 flex items-start justify-between"><div><div className="font-mono-app text-[10px] uppercase tracking-[.18em] text-muted-foreground">Throughput</div><h3 className="mt-1 text-lg font-extrabold tracking-[-.03em]">Milling volume</h3></div><div className="rounded-lg bg-secondary px-2 py-1 font-mono-app text-[10px] text-muted-foreground">kg / day</div></div><div className="flex h-48 items-end gap-2 border-b border-border/70 pb-0 sm:gap-4">{(data?.millingVolume ?? []).length > 0 ? data?.millingVolume.map((item, index) => { const max = Math.max(...(data?.millingVolume ?? []).map((point) => point.volume), 1); return <div key={item.label} className="group flex flex-1 flex-col items-center gap-2"><div className="relative w-full"><div className="mx-auto w-full max-w-11 rounded-t-lg bg-[hsl(var(--chart-1))] transition-all group-hover:bg-primary" style={{ height: `${Math.max(10, (item.volume / max) * 155)}px` }} title={`${item.volume} kg`} /></div><span className="font-mono-app text-[9px] text-muted-foreground">{item.label}</span></div> }) : <div className="flex w-full items-center justify-center text-xs text-muted-foreground">No volume recorded for this period</div>}</div></section><section className="rounded-2xl border border-border bg-card p-5 md:p-6"><div className="mb-5 flex items-center justify-between"><div><div className="font-mono-app text-[10px] uppercase tracking-[.18em] text-muted-foreground">Pulse</div><h3 className="mt-1 text-lg font-extrabold tracking-[-.03em]">Recent activity</h3></div><Link href="/notifications" className="text-xs font-bold text-primary hover:underline" data-testid="link-view-activity">View all</Link></div><div className="space-y-4">{activities.length === 0 ? <EmptyState label="No activity yet" /> : activities.slice(0, 5).map((item) => <div key={item.id} className="flex gap-3" data-testid={`activity-${item.id}`}><span className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${item.tone === 'warning' ? 'bg-accent' : item.tone === 'success' ? 'bg-[hsl(var(--chart-1))]' : item.tone === 'info' ? 'bg-[hsl(var(--chart-5))]' : 'bg-muted-foreground'}`} /><div className="min-w-0"><p className="text-xs font-bold">{item.title}</p><p className="mt-0.5 text-[11px] leading-5 text-muted-foreground">{item.description}</p><p className="mt-1 font-mono-app text-[9px] uppercase text-muted-foreground/70">{date(item.timestamp)}</p></div></div>)}</div></section></div></>}</AppShell>;
}

export function FarmersPage() {
  const [search, setSearch] = useState(''); const [dialog, setDialog] = useState(false); const [selected, setSelected] = useState<number | null>(null); const [form, setForm] = useState({ fullName: '', contactNumber: '', barangay: 'Camarin', sitio: 'Sitio Camarin', customerType: 'FARMER', riceVariety: 'Dinorado', farmArea: '' });
  const queryClient = useQueryClient(); const list = useListFarmers({ search: search || undefined, page: 1, pageSize: 50 }, { query: { keepPreviousData: true } }); const create = useCreateFarmer(); const update = useUpdateFarmer(); const remove = useDeleteFarmer(); const detail = useGetFarmer(selected ?? 0, { query: { enabled: !!selected, queryKey: getGetFarmerQueryKey(selected ?? 0) } });
  const items = list.data?.items ?? []; const openCreate = () => { setSelected(null); setForm({ fullName: '', contactNumber: '', barangay: 'Camarin', sitio: 'Sitio Camarin', customerType: 'FARMER', riceVariety: 'Dinorado', farmArea: '' }); setDialog(true); }; const save = (event: React.FormEvent) => { event.preventDefault(); const payload = { ...form, farmArea: Number(form.farmArea || 0), customerType: form.customerType as 'FARMER' | 'CUSTOMER' }; if (selected) update.mutate({ id: selected, data: payload }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListFarmersQueryKey() }); setDialog(false); } }); else create.mutate({ data: payload }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListFarmersQueryKey() }); setDialog(false); } }); };
  return <AppShell><PageIntro eyebrow="Relationships" title="Farmers & customers" description="The people behind every sack. Search the registry, review account health, and keep contact details current." action="Add person" onAction={openCreate} /><div className="mb-5 rounded-2xl border border-border bg-card p-4"><Toolbar search={search} setSearch={setSearch} placeholder="Search name, farmer code, barangay..." /></div>{list.isLoading ? <LoadingState label="Loading farmer registry" /> : list.isError ? <ErrorState retry={() => list.refetch()} /> : <TableFrame><table className="w-full min-w-[820px] text-left"><thead className="border-b border-border bg-secondary/45"><tr>{['Person', 'Location', 'Type', 'Activity', 'Balance', 'Status', ''].map((head) => <th key={head} className="px-5 py-4 font-mono-app text-[9px] uppercase tracking-[.16em] text-muted-foreground">{head}</th>)}</tr></thead>{items.length === 0 ? <TableEmpty colSpan={7} /> : <tbody className="divide-y divide-border/70">{items.map((farmer) => <tr key={farmer.id} className="group transition hover:bg-secondary/25" data-testid={`row-farmer-${farmer.id}`}><td className="px-5 py-4"><button className="flex items-center gap-3 text-left" onClick={() => { setSelected(farmer.id); setForm({ fullName: farmer.fullName, contactNumber: farmer.contactNumber ?? '', barangay: farmer.barangay, sitio: farmer.sitio, customerType: farmer.customerType, riceVariety: farmer.riceVariety ?? '', farmArea: String(farmer.farmArea ?? '') }); setDialog(true); }} data-testid={`button-edit-farmer-${farmer.id}`}><span className="grid h-9 w-9 place-items-center rounded-xl bg-accent/30 text-xs font-extrabold text-primary">{farmer.fullName.split(' ').map((part) => part[0]).join('').slice(0, 2)}</span><span><span className="block text-sm font-bold">{farmer.fullName}</span><span className="font-mono-app text-[9px] uppercase tracking-wider text-muted-foreground">{farmer.farmerCode} · {farmer.customerNumber}</span></span></button></td><td className="px-5 py-4 text-xs text-muted-foreground">{farmer.barangay}<br /><span className="text-[11px]">{farmer.sitio}</span></td><td className="px-5 py-4"><StatusPill value={farmer.customerType} tone="blue" /></td><td className="px-5 py-4 text-sm font-bold">{farmer.transactionCount ?? 0}<span className="ml-1 text-[10px] font-normal text-muted-foreground">batches</span></td><td className="px-5 py-4 font-mono-app text-xs">{peso(farmer.balance)}</td><td className="px-5 py-4"><StatusPill value={farmer.status} /></td><td className="px-5 py-4 text-right"><button onClick={() => { if (window.confirm(`Remove ${farmer.fullName} from the active registry?`)) remove.mutate({ id: farmer.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListFarmersQueryKey() }) }); }} className="rounded-lg p-2 text-muted-foreground opacity-0 transition hover:bg-destructive/10 hover:text-destructive group-hover:opacity-100" data-testid={`button-delete-farmer-${farmer.id}`}><X size={15} /></button></td></tr>)}</tbody>}</table></TableFrame>}<Dialog open={dialog} onOpenChange={setDialog}><DialogContent><DialogHeader><DialogTitle>{selected ? 'Update person record' : 'Add to the registry'}</DialogTitle><DialogDescription>Keep the details precise; they appear on receiving slips and account statements.</DialogDescription></DialogHeader><form onSubmit={save} className="grid gap-4 sm:grid-cols-2"><label className="sm:col-span-2"><span className="field-label">Full name</span><Input required value={form.fullName} onChange={(event) => setForm({ ...form, fullName: event.target.value })} data-testid="input-farmer-name" /></label><label><span className="field-label">Contact number</span><Input required value={form.contactNumber} onChange={(event) => setForm({ ...form, contactNumber: event.target.value })} data-testid="input-farmer-contact" /></label><label><span className="field-label">Person type</span><select value={form.customerType} onChange={(event) => setForm({ ...form, customerType: event.target.value })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid="select-farmer-type"><option value="FARMER">Farmer</option><option value="CUSTOMER">Customer</option></select></label><label><span className="field-label">Barangay</span><Input value={form.barangay} onChange={(event) => setForm({ ...form, barangay: event.target.value })} data-testid="input-farmer-barangay" /></label><label><span className="field-label">Sitio</span><Input value={form.sitio} onChange={(event) => setForm({ ...form, sitio: event.target.value })} data-testid="input-farmer-sitio" /></label><label><span className="field-label">Rice variety</span><Input value={form.riceVariety} onChange={(event) => setForm({ ...form, riceVariety: event.target.value })} data-testid="input-farmer-variety" /></label><label><span className="field-label">Farm area (ha)</span><Input type="number" min="0" step=".01" value={form.farmArea} onChange={(event) => setForm({ ...form, farmArea: event.target.value })} data-testid="input-farmer-area" /></label><DialogFooter className="sm:col-span-2"><Button type="button" variant="outline" onClick={() => setDialog(false)} data-testid="button-cancel-farmer">Cancel</Button><Button type="submit" disabled={create.isPending || update.isPending} data-testid="button-save-farmer">{create.isPending || update.isPending ? <Loader2 className="animate-spin" size={15} /> : <Check size={15} />} Save record</Button></DialogFooter></form></DialogContent></Dialog>{selected && detail.data && <span className="sr-only" data-testid="detail-farmer-loaded">{detail.data.fullName}</span>}</AppShell>;
}

export function MillingPage() {
  const [search, setSearch] = useState(''); const [dialog, setDialog] = useState(false); const [selected, setSelected] = useState<number | null>(null); const [form, setForm] = useState({ farmerId: '', riceVariety: 'Dinorado', riceType: 'Palay', quantityReceived: '', millingType: 'Custom milling', remarks: '' }); const queryClient = useQueryClient(); const list = useListMillingTransactions({ search: search || undefined, page: 1, pageSize: 50 }, { query: { keepPreviousData: true } }); const create = useCreateMillingTransaction(); const update = useUpdateMillingTransaction(); const detail = useGetMillingTransaction(selected ?? 0, { query: { enabled: !!selected, queryKey: getGetMillingTransactionQueryKey(selected ?? 0) } }); const farmers = useListFarmers({ page: 1, pageSize: 100 }, { query: { staleTime: 60000 } }); const items = list.data?.items ?? []; const save = (event: React.FormEvent) => { event.preventDefault(); create.mutate({ data: { farmerId: Number(form.farmerId), riceVariety: form.riceVariety, riceType: form.riceType, quantityReceived: Number(form.quantityReceived), millingType: form.millingType, remarks: form.remarks } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListMillingTransactionsQueryKey() }); setDialog(false); } }); }; const advance = (transaction: MillingTransaction) => { const statuses = ['PENDING', 'RECEIVED', 'WEIGHING', 'PROCESSING', 'QUALITY_CHECK', 'READY_FOR_RELEASE', 'COMPLETED']; const next = statuses[Math.min(statuses.indexOf(transaction.status) + 1, statuses.length - 1)] as 'PENDING'; update.mutate({ id: transaction.id, data: { status: next } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListMillingTransactionsQueryKey() }) }); };
  return <AppShell><PageIntro eyebrow="Floor control" title="Milling pipeline" description="Every batch has a next clear move. Receive, weigh, process, quality-check, and release without losing the thread." action="Receive palay" onAction={() => setDialog(true)} /><div className="mb-5 rounded-2xl border border-border bg-card p-4"><Toolbar search={search} setSearch={setSearch} placeholder="Search transaction, farmer, variety..." /></div>{list.isLoading ? <LoadingState label="Loading milling floor" /> : list.isError ? <ErrorState retry={() => list.refetch()} /> : items.length === 0 ? <EmptyState label="No milling batches yet" action="Receive first batch" onAction={() => setDialog(true)} /> : <TableFrame><table className="w-full min-w-[980px] text-left"><thead className="border-b border-border bg-secondary/45"><tr>{['Batch', 'Farmer', 'Input', 'Received', 'Expected', 'Value', 'Stage', ''].map((head) => <th key={head} className="px-5 py-4 font-mono-app text-[9px] uppercase tracking-[.16em] text-muted-foreground">{head}</th>)}</tr></thead><tbody className="divide-y divide-border/70">{items.map((item) => <tr key={item.id} className="group transition hover:bg-secondary/25" data-testid={`row-milling-${item.id}`}><td className="px-5 py-4"><button onClick={() => setSelected(item.id)} className="text-left" data-testid={`button-view-milling-${item.id}`}><span className="block font-mono-app text-xs font-medium text-primary">{item.transactionCode}</span><span className="mt-1 block text-[10px] text-muted-foreground">{date(item.dateReceived)}</span></button></td><td className="px-5 py-4 text-sm font-bold">{item.farmerName}</td><td className="px-5 py-4"><span className="block text-sm font-bold">{item.quantityReceived.toLocaleString()} kg</span><span className="text-[10px] text-muted-foreground">{item.riceVariety} · {item.riceType}</span></td><td className="px-5 py-4 text-xs text-muted-foreground">{date(item.dateReceived)}</td><td className="px-5 py-4 text-xs text-muted-foreground">{date(item.expectedCompletion)}</td><td className="px-5 py-4 font-mono-app text-xs">{peso(item.totalAmount)}</td><td className="px-5 py-4"><button onClick={() => advance(item)} title="Advance to next stage" data-testid={`button-advance-milling-${item.id}`}><StatusPill value={item.status} /></button></td><td className="px-5 py-4 text-right"><MoreHorizontal size={16} className="ml-auto text-muted-foreground" /></td></tr>)}</tbody></table></TableFrame>}<Dialog open={dialog} onOpenChange={setDialog}><DialogContent><DialogHeader><DialogTitle>Receive a new palay batch</DialogTitle><DialogDescription>Start the chain of custody with the weight and variety at the receiving desk.</DialogDescription></DialogHeader><form onSubmit={save} className="grid gap-4 sm:grid-cols-2"><label className="sm:col-span-2"><span className="field-label">Farmer / customer</span><select required value={form.farmerId} onChange={(event) => setForm({ ...form, farmerId: event.target.value })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid="select-milling-farmer"><option value="">Select account</option>{(farmers.data?.items ?? []).map((farmer) => <option key={farmer.id} value={farmer.id}>{farmer.fullName} · {farmer.farmerCode}</option>)}</select></label><label><span className="field-label">Quantity received (kg)</span><Input required type="number" min="0" value={form.quantityReceived} onChange={(event) => setForm({ ...form, quantityReceived: event.target.value })} data-testid="input-milling-quantity" /></label><label><span className="field-label">Rice variety</span><Input required value={form.riceVariety} onChange={(event) => setForm({ ...form, riceVariety: event.target.value })} data-testid="input-milling-variety" /></label><label><span className="field-label">Rice type</span><Input required value={form.riceType} onChange={(event) => setForm({ ...form, riceType: event.target.value })} data-testid="input-milling-type" /></label><label><span className="field-label">Milling type</span><Input required value={form.millingType} onChange={(event) => setForm({ ...form, millingType: event.target.value })} data-testid="input-milling-service" /></label><label className="sm:col-span-2"><span className="field-label">Remarks</span><Textarea value={form.remarks} onChange={(event) => setForm({ ...form, remarks: event.target.value })} data-testid="input-milling-remarks" /></label><DialogFooter className="sm:col-span-2"><Button type="button" variant="outline" onClick={() => setDialog(false)} data-testid="button-cancel-milling">Cancel</Button><Button type="submit" disabled={create.isPending} data-testid="button-save-milling">{create.isPending ? <Loader2 className="animate-spin" size={15} /> : <Check size={15} />} Start batch</Button></DialogFooter></form></DialogContent></Dialog>{selected && detail.data && <Dialog open={!!selected} onOpenChange={(open) => !open && setSelected(null)}><DialogContent><DialogHeader><DialogTitle>{detail.data.transactionCode}</DialogTitle><DialogDescription>{detail.data.farmerName} · {detail.data.riceVariety}</DialogDescription></DialogHeader><div className="space-y-5"><div className="flex items-center justify-between"><StatusPill value={detail.data.status} /><span className="font-mono-app text-xs">{detail.data.progressStep ?? 0} / 6 steps</span></div><div className="h-2 overflow-hidden rounded-full bg-secondary"><div className="h-full rounded-full bg-accent transition-all" style={{ width: `${Math.min(100, ((detail.data.progressStep ?? 0) / 6) * 100)}%` }} /></div><div className="grid grid-cols-2 gap-3 text-sm"><div className="rounded-xl bg-secondary/55 p-3"><span className="block text-[10px] text-muted-foreground">Received</span><b>{detail.data.quantityReceived.toLocaleString()} kg</b></div><div className="rounded-xl bg-secondary/55 p-3"><span className="block text-[10px] text-muted-foreground">Balance</span><b>{peso(detail.data.balance)}</b></div></div></div></DialogContent></Dialog>}</AppShell>;
}

export function InventoryPage() {
  const [search, setSearch] = useState(''); const [dialog, setDialog] = useState(false); const [form, setForm] = useState({ itemName: '', category: 'RAW_MATERIAL', variety: '', unit: 'kg', currentStock: '', minimumStock: '', maximumStock: '', unitCost: '', sellingPrice: '', supplier: '', storageLocation: '' }); const queryClient = useQueryClient(); const list = useListInventory({ search: search || undefined, page: 1, pageSize: 100 }, { query: { keepPreviousData: true } }); const create = useCreateInventoryItem(); const update = useUpdateInventoryItem(); const save = (event: React.FormEvent) => { event.preventDefault(); create.mutate({ data: { ...form, category: form.category as 'RAW_MATERIAL', currentStock: Number(form.currentStock), minimumStock: Number(form.minimumStock), maximumStock: Number(form.maximumStock), unitCost: Number(form.unitCost), sellingPrice: Number(form.sellingPrice || 0) } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListInventoryQueryKey() }); setDialog(false); } }); }; const items = list.data?.items ?? []; const low = list.data?.lowStockCount ?? items.filter((item) => item.stockStatus !== 'HEALTHY').length;
  return <AppShell><PageIntro eyebrow="Stock room" title="Inventory" description="Know what is on hand before the next batch arrives. Low stock is surfaced early, not after the bin is empty." action="Add inventory item" onAction={() => setDialog(true)} /><div className="mb-5 grid gap-4 md:grid-cols-3"><StatCard label="Tracked items" value={String(list.data?.total ?? items.length)} meta="across all categories" icon={PackageOpen} /><StatCard label="Needs attention" value={String(low)} meta="low or out of stock" icon={CircleAlert} accent="gold" /><StatCard label="Stock value" value={peso(items.reduce((sum, item) => sum + item.currentStock * item.unitCost, 0))} meta="current cost basis" icon={Banknote} /></div><div className="mb-5 rounded-2xl border border-border bg-card p-4"><Toolbar search={search} setSearch={setSearch} placeholder="Search item, variety, storage location..." /></div>{list.isLoading ? <LoadingState label="Checking stock room" /> : list.isError ? <ErrorState retry={() => list.refetch()} /> : items.length === 0 ? <EmptyState label="Inventory is empty" action="Add first item" onAction={() => setDialog(true)} /> : <TableFrame><table className="w-full min-w-[880px] text-left"><thead className="border-b border-border bg-secondary/45"><tr>{['Item', 'Category', 'On hand', 'Par level', 'Cost basis', 'Location', 'Status', ''].map((head) => <th key={head} className="px-5 py-4 font-mono-app text-[9px] uppercase tracking-[.16em] text-muted-foreground">{head}</th>)}</tr></thead><tbody className="divide-y divide-border/70">{items.map((item) => <tr key={item.id} className="group transition hover:bg-secondary/25" data-testid={`row-inventory-${item.id}`}><td className="px-5 py-4"><span className="block text-sm font-bold">{item.itemName}</span><span className="font-mono-app text-[9px] uppercase text-muted-foreground">{item.itemCode} {item.variety ? `· ${item.variety}` : ''}</span></td><td className="px-5 py-4"><StatusPill value={item.category} tone="blue" /></td><td className="px-5 py-4"><span className={`text-sm font-extrabold ${item.stockStatus !== 'HEALTHY' ? 'text-[hsl(var(--chart-4))]' : 'text-primary'}`}>{item.currentStock.toLocaleString()} {item.unit}</span><div className="mt-2 h-1.5 w-24 overflow-hidden rounded-full bg-secondary"><div className={`h-full ${item.stockStatus === 'OUT_OF_STOCK' ? 'bg-[hsl(var(--chart-4))]' : item.stockStatus === 'LOW_STOCK' ? 'bg-accent' : 'bg-[hsl(var(--chart-1))]'}`} style={{ width: `${Math.min(100, (item.currentStock / Math.max(item.maximumStock, 1)) * 100)}%` }} /></div></td><td className="px-5 py-4 text-xs text-muted-foreground">{item.minimumStock}–{item.maximumStock} {item.unit}</td><td className="px-5 py-4 font-mono-app text-xs">{peso(item.currentStock * item.unitCost)}</td><td className="px-5 py-4 text-xs text-muted-foreground">{item.storageLocation ?? 'Unassigned'}</td><td className="px-5 py-4"><StatusPill value={item.stockStatus} /></td><td className="px-5 py-4 text-right"><button onClick={() => { const amount = window.prompt(`Adjust ${item.itemName} stock by (use a negative number to remove):`, '0'); if (amount !== null && !Number.isNaN(Number(amount))) update.mutate({ id: item.id, data: { adjustment: Number(amount) } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListInventoryQueryKey() }) }); }} className="rounded-lg border border-border px-2 py-1 text-[10px] font-bold text-muted-foreground opacity-0 transition hover:border-primary hover:text-primary group-hover:opacity-100" data-testid={`button-adjust-inventory-${item.id}`}>Adjust</button></td></tr>)}</tbody></table></TableFrame>}<Dialog open={dialog} onOpenChange={setDialog}><DialogContent><DialogHeader><DialogTitle>Add inventory item</DialogTitle><DialogDescription>Set a practical par range so the desk knows when to reorder.</DialogDescription></DialogHeader><form onSubmit={save} className="grid gap-4 sm:grid-cols-2">{[['itemName','Item name','text'],['variety','Variety','text'],['unit','Unit','text'],['currentStock','Current stock','number'],['minimumStock','Minimum stock','number'],['maximumStock','Maximum stock','number'],['unitCost','Unit cost','number'],['sellingPrice','Selling price','number'],['supplier','Supplier','text'],['storageLocation','Storage location','text']].map(([key,label,type]) => <label key={key}><span className="field-label">{label}</span><Input required={['itemName','unit','currentStock','minimumStock','maximumStock','unitCost'].includes(key)} type={type} value={form[key as keyof typeof form]} onChange={(event) => setForm({ ...form, [key]: event.target.value })} data-testid={`input-inventory-${key}`} /></label>)}<label><span className="field-label">Category</span><select value={form.category} onChange={(event) => setForm({ ...form, category: event.target.value })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid="select-inventory-category"><option value="RAW_MATERIAL">Raw material</option><option value="FINISHED_PRODUCT">Finished product</option><option value="BY_PRODUCT">By-product</option><option value="PACKAGING">Packaging</option></select></label><DialogFooter className="sm:col-span-2"><Button type="button" variant="outline" onClick={() => setDialog(false)} data-testid="button-cancel-inventory">Cancel</Button><Button type="submit" disabled={create.isPending} data-testid="button-save-inventory">{create.isPending ? <Loader2 className="animate-spin" size={15} /> : <Check size={15} />} Add item</Button></DialogFooter></form></DialogContent></Dialog></AppShell>;
}

export function PaymentsPage({ portal = false }: { portal?: boolean }) {
  const [search, setSearch] = useState(''); const [dialog, setDialog] = useState(false); const [form, setForm] = useState({ transactionId: '', amount: '', paymentMethod: 'CASH', referenceNumber: '', remarks: '' }); const queryClient = useQueryClient(); const list = useListPayments({ search: search || undefined, page: 1, pageSize: 100 }, { query: { keepPreviousData: true } }); const create = useCreatePayment(); const transactions = useListMillingTransactions({ page: 1, pageSize: 100 }, { query: { enabled: !portal, queryKey: getListMillingTransactionsQueryKey({ page: 1, pageSize: 100 }) } }); const save = (event: React.FormEvent) => { event.preventDefault(); create.mutate({ data: { transactionId: Number(form.transactionId), amount: Number(form.amount), paymentMethod: form.paymentMethod as 'CASH', referenceNumber: form.referenceNumber, remarks: form.remarks } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListPaymentsQueryKey() }); setDialog(false); } }); }; const items = list.data?.items ?? []; return <AppShell portal={portal}><PageIntro eyebrow={portal ? 'Private ledger' : 'Finance desk'} title={portal ? 'Payments & balances' : 'Payments'} description={portal ? 'Your payment history and current balance, kept private to your account.' : 'Record collections against a batch and keep outstanding balances visible to the whole desk.'} action={!portal ? 'Record payment' : undefined} onAction={!portal ? () => setDialog(true) : undefined} /><div className="mb-5 grid gap-4 sm:grid-cols-3"><StatCard label="Collected" value={peso(list.data?.totalPaid)} meta="in this view" icon={Banknote} /><StatCard label="Outstanding" value={peso(list.data?.outstanding)} meta="needs follow-up" icon={CircleAlert} accent="gold" /><StatCard label="Entries" value={String(list.data?.total ?? items.length)} meta="payment records" icon={ClipboardList} /></div><div className="mb-5 rounded-2xl border border-border bg-card p-4"><Toolbar search={search} setSearch={setSearch} placeholder="Search payment code, transaction, name..." /></div>{list.isLoading ? <LoadingState label="Loading payment ledger" /> : list.isError ? <ErrorState retry={() => list.refetch()} /> : items.length === 0 ? <EmptyState label="No payments in this view" action={!portal ? 'Record first payment' : undefined} onAction={!portal ? () => setDialog(true) : undefined} /> : <TableFrame><table className="w-full min-w-[780px] text-left"><thead className="border-b border-border bg-secondary/45"><tr>{['Payment', 'Account', 'Transaction', 'Date', 'Method', 'Amount', 'Received by'].map((head) => <th key={head} className="px-5 py-4 font-mono-app text-[9px] uppercase tracking-[.16em] text-muted-foreground">{head}</th>)}</tr></thead><tbody className="divide-y divide-border/70">{items.map((item) => <tr key={item.id} className="transition hover:bg-secondary/25" data-testid={`row-payment-${item.id}`}><td className="px-5 py-4 font-mono-app text-xs font-medium text-primary">{item.paymentCode}</td><td className="px-5 py-4 text-sm font-bold">{item.customerName}</td><td className="px-5 py-4 font-mono-app text-[10px] text-muted-foreground">{item.transactionCode}</td><td className="px-5 py-4 text-xs text-muted-foreground">{date(item.date)}</td><td className="px-5 py-4"><StatusPill value={item.paymentMethod} tone="blue" /></td><td className="px-5 py-4 font-mono-app text-xs font-medium">{peso(item.amount)}</td><td className="px-5 py-4 text-xs text-muted-foreground">{item.receivedBy ?? '—'}</td></tr>)}</tbody></table></TableFrame>}<Dialog open={dialog} onOpenChange={setDialog}><DialogContent><DialogHeader><DialogTitle>Record a payment</DialogTitle><DialogDescription>Post the collection to the correct milling transaction.</DialogDescription></DialogHeader><form onSubmit={save} className="grid gap-4"><label><span className="field-label">Milling transaction</span><select required value={form.transactionId} onChange={(event) => setForm({ ...form, transactionId: event.target.value })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid="select-payment-transaction"><option value="">Select batch</option>{(transactions.data?.items ?? []).map((transaction) => <option key={transaction.id} value={transaction.id}>{transaction.transactionCode} · {transaction.farmerName} · balance {peso(transaction.balance)}</option>)}</select></label><div className="grid gap-4 sm:grid-cols-2"><label><span className="field-label">Amount</span><Input required type="number" min="0" step=".01" value={form.amount} onChange={(event) => setForm({ ...form, amount: event.target.value })} data-testid="input-payment-amount" /></label><label><span className="field-label">Payment method</span><select value={form.paymentMethod} onChange={(event) => setForm({ ...form, paymentMethod: event.target.value })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid="select-payment-method"><option value="CASH">Cash</option><option value="BANK_TRANSFER">Bank transfer</option><option value="GCASH">GCash</option><option value="OTHER">Other</option></select></label></div><label><span className="field-label">Reference number</span><Input value={form.referenceNumber} onChange={(event) => setForm({ ...form, referenceNumber: event.target.value })} data-testid="input-payment-reference" /></label><label><span className="field-label">Remarks</span><Textarea value={form.remarks} onChange={(event) => setForm({ ...form, remarks: event.target.value })} data-testid="input-payment-remarks" /></label><DialogFooter><Button type="button" variant="outline" onClick={() => setDialog(false)} data-testid="button-cancel-payment">Cancel</Button><Button type="submit" disabled={create.isPending} data-testid="button-save-payment">{create.isPending ? <Loader2 className="animate-spin" size={15} /> : <Check size={15} />} Post payment</Button></DialogFooter></form></DialogContent></Dialog></AppShell>;
}

export function ReportsPage() {
  const [period, setPeriod] = useState<'today' | 'week' | 'month' | 'year'>('month'); const report = useGetReportsSummary({ period }, { query: { queryKey: getGetReportsSummaryQueryKey({ period }), retry: false } }); const data = report.data; return <AppShell><PageIntro eyebrow="Decision support" title="Report center" description="A clean read on money, production, and recovery for the selected period." /><div className="mb-6 flex items-center justify-between"><div className="font-mono-app text-[10px] uppercase tracking-[.18em] text-muted-foreground">Reporting period</div><div className="flex rounded-xl border border-border bg-card p-1">{(['today','week','month','year'] as const).map((item) => <button key={item} onClick={() => setPeriod(item)} className={`rounded-lg px-3 py-2 font-mono-app text-[10px] uppercase ${period === item ? 'bg-primary text-primary-foreground' : 'text-muted-foreground'}`} data-testid={`button-report-${item}`}>{item}</button>)}</div></div>{report.isLoading ? <LoadingState label="Assembling report" /> : report.isError ? <ErrorState retry={() => report.refetch()} /> : !data ? <EmptyState label="No report data for this period" /> : <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Revenue" value={peso(data.revenue)} meta="gross service value" icon={TrendingUp} /><StatCard label="Payments" value={peso(data.payments)} meta="cash received" icon={Banknote} /><StatCard label="Expenses" value={peso(data.expenses)} meta="recorded operating cost" icon={ArrowDownRight} accent="gold" /><StatCard label="Net income" value={peso(data.netIncome)} meta="after recorded expenses" icon={ArrowUpRight} /></div><div className="mt-5 grid gap-5 md:grid-cols-2"><section className="rounded-2xl border border-border bg-card p-6"><div className="font-mono-app text-[10px] uppercase tracking-[.18em] text-muted-foreground">Production ledger</div><h3 className="mt-1 text-xl font-extrabold tracking-[-.03em]">Input to output</h3><div className="mt-8 space-y-5">{[['Palay input', data.production.input, 'bg-primary'], ['Milled output', data.production.milled, 'bg-accent']].map(([label, value, color]) => <div key={String(label)}><div className="mb-2 flex justify-between text-sm"><span className="font-bold">{label}</span><span className="font-mono-app text-xs">{Number(value).toLocaleString()} kg</span></div><div className="h-3 overflow-hidden rounded-full bg-secondary"><div className={`h-full rounded-full ${color}`} style={{ width: `${Math.min(100, (Number(value) / Math.max(data.production.input, 1)) * 100)}%` }} /></div></div>)}<div className="mt-7 flex items-center justify-between border-t border-border pt-5"><span className="text-sm text-muted-foreground">Recovery rate</span><strong className="font-display text-3xl text-primary">{data.production.recoveryRate.toFixed(1)}%</strong></div></div></section><section className="rounded-2xl border border-border bg-primary p-6 text-primary-foreground"><div className="flex items-center justify-between"><div><div className="font-mono-app text-[10px] uppercase tracking-[.18em] text-primary-foreground/55">Accounts receivable</div><h3 className="mt-1 text-xl font-extrabold">Outstanding balance</h3></div><FileDown size={19} className="text-accent" /></div><div className="mt-10 font-display text-5xl text-accent">{peso(data.outstandingBalance)}</div><p className="mt-3 max-w-xs text-sm leading-6 text-primary-foreground/60">Keep this number close when planning collections and release schedules.</p><Button variant="secondary" className="mt-8" onClick={() => window.print()} data-testid="button-export-report"><FileDown size={15} /> Print report</Button></section></div></>}</AppShell>;
}

export function NotificationsPage() {
  const list = useListNotifications({ query: { retry: false } }); const items = list.data ?? []; return <AppShell><PageIntro eyebrow="Workspace signal" title="Notifications" description="Operational notes, payment events, and stock warnings that need a human eye." />{list.isLoading ? <LoadingState label="Checking notifications" /> : list.isError ? <ErrorState retry={() => list.refetch()} /> : items.length === 0 ? <EmptyState label="You are all caught up" /> : <div className="max-w-3xl space-y-3">{items.map((item) => <div key={item.id} className={`flex gap-4 rounded-2xl border p-5 transition hover:-translate-y-0.5 ${item.unread ? 'border-accent/60 bg-accent/10' : 'border-border bg-card'}`} data-testid={`notification-${item.id}`}><span className="mt-1 grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-primary text-accent"><BellIcon type={item.type} /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-start justify-between gap-2"><h3 className="text-sm font-extrabold">{item.title}</h3>{item.unread && <StatusPill value="UNREAD" tone="gold" />}</div><p className="mt-1 text-sm leading-6 text-muted-foreground">{item.message}</p><div className="mt-3 font-mono-app text-[9px] uppercase tracking-[.12em] text-muted-foreground">{titleCase(item.type)} · {date(item.createdAt)}</div></div></div>)}</div>}</AppShell>;
}
function BellIcon({ type }: { type: string }) { return type === 'PAYMENT' ? <Banknote size={16} /> : type === 'INVENTORY' ? <PackageOpen size={16} /> : <Wheat size={16} />; }
export function SettingsPage() { const current = useGetCurrentUser({ query: { retry: false } }); return <AppShell><PageIntro eyebrow="Workspace preferences" title="Settings" description="A quiet place for account details and the desk's operating context." /><div className="grid max-w-4xl gap-5 md:grid-cols-[.75fr_1.25fr]"><section className="rounded-2xl border border-border bg-primary p-6 text-primary-foreground"><div className="grid h-14 w-14 place-items-center overflow-hidden rounded-2xl bg-accent"><Initials name={current.data?.name ?? 'Operator'} /></div><h3 className="mt-5 font-display text-3xl">{current.data?.name ?? 'Camarin operator'}</h3><p className="mt-1 text-sm text-primary-foreground/60">{current.data?.email ?? 'Demo account'}</p><StatusPill value={current.data?.role ?? 'ADMIN'} tone="gold" /></section><section className="rounded-2xl border border-border bg-card p-6"><div className="mb-6 flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-secondary text-primary"><Settings2 size={17} /></span><div><h3 className="font-extrabold">Mill profile</h3><p className="text-xs text-muted-foreground">Context shown across the workspace</p></div></div><div className="divide-y divide-border/70">{[['Mill name','Sitio Camarin Rice Mill'],['Location','Dimataling, Zamboanga del Sur'],['Timezone','Asia/Manila (PHT)'],['System status','Connected']].map(([label, value]) => <div key={label} className="flex items-center justify-between py-4 text-sm"><span className="text-muted-foreground">{label}</span><span className="font-bold">{value}</span></div>)}</div><Button variant="outline" className="mt-5" onClick={() => window.alert('Preferences are saved by the operations administrator.')} data-testid="button-settings-save"><Check size={15} /> Preferences are up to date</Button></section></div></AppShell>; }
export function AccessDeniedPage() { return <div className="grid min-h-[100dvh] place-items-center bg-background p-6"><div className="max-w-md text-center page-enter"><div className="mx-auto grid h-16 w-16 place-items-center rounded-2xl bg-[hsl(var(--chart-4)/.12)] text-[hsl(var(--chart-4))]"><ShieldCheck size={28} /></div><div className="mt-6 font-mono-app text-[10px] uppercase tracking-[.2em] text-muted-foreground">Error 403</div><h1 className="mt-2 font-display text-5xl tracking-[-.04em] text-primary">Not your desk.</h1><p className="mt-4 text-sm leading-6 text-muted-foreground">This view is private to another role. Return to your workspace and keep the right records in the right hands.</p><Link href="/" className="mt-7 inline-flex h-10 items-center gap-2 rounded-md bg-primary px-5 text-sm font-semibold text-primary-foreground" data-testid="link-access-home">Return to sign in</Link></div></div>; }